// Data source: data/stock-descriptions.csv (50 stocks across 5 sectors).

const CHART_WIDTH = 780;
const CHART_HEIGHT = 620;

// Fixed sector order so colors and legend are deterministic.
const SECTORS = ["Information Technology", "Financial", "Energy", "Industry", "ETF"];
const SECTOR_COLORS = {
    "Information Technology": "#4e79a7",
    "Financial":              "#59a14f",
    "Energy":                 "#e15759",
    "Industry":               "#f28e2b",
    "ETF":                    "#9c755f"
};

// Uniform bubble radius for ETFs (they lack a market cap).
const ETF_RADIUS = 28;

const tooltip = d3.select("#tooltip");

d3.csv("data/stock-descriptions.csv", d => ({
    ticker:    d.ticker,
    sector:    d.sector,
    name:      d["full name"],
    marketCap: d.marketCap ? +d.marketCap : null,
    country:   d.country || "",
    website:   d.website || ""
})).then(data => {
    // Stable sort: by sector (in SECTORS order), then by market cap desc, then by ticker.
    const sectorIndex = new Map(SECTORS.map((s, i) => [s, i]));
    data.sort((a, b) => {
        const sa = sectorIndex.get(a.sector) ?? 99;
        const sb = sectorIndex.get(b.sector) ?? 99;
        if (sa !== sb) return sa - sb;
        const ma = a.marketCap ?? -1;
        const mb = b.marketCap ?? -1;
        if (mb !== ma) return mb - ma;
        return d3.ascending(a.ticker, b.ticker);
    });

    renderChart(data);
    renderTable(data);
});

// -----------------------------------------------------------
// Bubble chart
// -----------------------------------------------------------
function renderChart(data) {
    // Radius scale for non-ETFs. Use sqrt so area ~ marketCap.
    const nonEtfCaps = data.filter(d => d.marketCap).map(d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
        .domain([d3.min(nonEtfCaps), d3.max(nonEtfCaps)])
        .range([14, 56]);

    data.forEach(d => {
        d.radius = d.marketCap ? radiusScale(d.marketCap) : ETF_RADIUS;
    });

    // Place sector centers in a compact arrangement so clusters stay close to center.
    const cx = CHART_WIDTH / 2;
    const cy = CHART_HEIGHT / 2;
    const ring = Math.min(CHART_WIDTH, CHART_HEIGHT) * 0.28;
    const sectorCenters = {};
    const angleStart = -Math.PI / 2; // first cluster at top
    SECTORS.forEach((s, i) => {
        const theta = angleStart + (2 * Math.PI * i) / SECTORS.length;
        sectorCenters[s] = {
            x: cx + ring * Math.cos(theta),
            y: cy + ring * Math.sin(theta)
        };
    });

    // Deterministic initial positions near sector centers (avoids random layout).
    data.forEach((d, i) => {
        const c = sectorCenters[d.sector] || { x: cx, y: cy };
        const offset = (i * 37) % 20 - 10;
        d.x = c.x + offset;
        d.y = c.y + offset;
    });

    const svg = d3.select("#chart")
        .append("svg")
        .attr("viewBox", `0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`)
        .attr("preserveAspectRatio", "xMidYMid meet");

    // Groups per bubble (circle + label).
    const node = svg.selectAll("g.node")
        .data(data, d => d.ticker)
        .enter()
        .append("g")
        .attr("class", "node")
        .attr("data-ticker", d => d.ticker);

    node.append("circle")
        .attr("class", "bubble")
        .attr("r", d => d.radius)
        .attr("fill", d => SECTOR_COLORS[d.sector] || "#888");

    node.append("text")
        .attr("class", "bubble-label")
        .text(d => d.ticker)
        .attr("font-size", d => Math.max(9, Math.min(14, d.radius / 2.4)));

    // Interactivity: hover tooltip (skip ETFs), click to select.
    node
        .on("mouseover", function (event, d) {
            if (d.sector === "ETF") return;
            tooltip
                .classed("visible", true)
                .html(`
                    <div class="tt-ticker">${escapeHtml(d.ticker)} &middot; ${formatMarketCap(d.marketCap)}</div>
                    <div>${escapeHtml(d.name)}</div>
                    <div class="tt-sector">${escapeHtml(d.sector)}</div>
                `);
        })
        .on("mousemove", function (event, d) {
            if (d.sector === "ETF") return;
            tooltip
                .style("left", (event.pageX + 14) + "px")
                .style("top",  (event.pageY + 14) + "px");
        })
        .on("mouseout", function () {
            tooltip.classed("visible", false);
        })
        .on("click", function (event, d) {
            selectTicker(d.ticker);
        });

